import{_ as a,a as o,b as s}from"./chunks/completed.B5AU_Dhd.js";import{_ as t,c as r,o as i,ae as n}from"./chunks/framework.DBgX5bsf.js";const _=JSON.parse('{"title":"Gestion des Commandes dans Drupal Commerce","description":"","frontmatter":{},"headers":[],"relativePath":"fr/docs/commerce/commandes.md","filePath":"fr/docs/commerce/commandes.md"}'),l={name:"fr/docs/commerce/commandes.md"};function d(m,e,u,c,p,f){return i(),r("div",null,e[0]||(e[0]=[n('<h1 id="gestion-des-commandes-dans-drupal-commerce" tabindex="-1">Gestion des Commandes dans Drupal Commerce <a class="header-anchor" href="#gestion-des-commandes-dans-drupal-commerce" aria-label="Permalink to &quot;Gestion des Commandes dans Drupal Commerce&quot;">​</a></h1><p>La gestion des commandes est une étape cruciale dans le fonctionnement d&#39;une plateforme e-commerce. Elle permet de suivre, traiter et expédier les commandes de manière efficace. Dans Drupal Commerce, les commandes sont gérées via l&#39;onglet <strong>Commandes</strong> dans l&#39;interface d&#39;administration. Voici un guide détaillé pour traiter les commandes après un achat sur votre site.</p><h2 id="acceder-a-la-liste-des-commandes" tabindex="-1"><strong>Accéder à la Liste des Commandes</strong> <a class="header-anchor" href="#acceder-a-la-liste-des-commandes" aria-label="Permalink to &quot;**Accéder à la Liste des Commandes**&quot;">​</a></h2><p>Pour accéder à la liste des commandes, suivez ces étapes :</p><ol><li>Rendez-vous dans le menu <strong>Commerce</strong> -&gt; <strong>Commandes</strong>.</li><li>Vous verrez une liste de toutes les commandes passées sur votre site.</li></ol><h2 id="consulter-les-details-d-une-commande" tabindex="-1"><strong>Consulter les Détails d&#39;une Commande</strong> <a class="header-anchor" href="#consulter-les-details-d-une-commande" aria-label="Permalink to &quot;**Consulter les Détails d&#39;une Commande**&quot;">​</a></h2><p>Pour consulter les détails d&#39;une commande spécifique :</p><ol><li>Cliquez sur le lien <strong>Voir</strong> correspondant à la commande souhaitée.</li><li>Vous aurez accès à toutes les informations relatives à la commande, y compris les produits, les informations client, les détails de livraison et de facturation.</li></ol><h2 id="traiter-une-commande" tabindex="-1"><strong>Traiter une Commande</strong> <a class="header-anchor" href="#traiter-une-commande" aria-label="Permalink to &quot;**Traiter une Commande**&quot;">​</a></h2><p>Le traitement d&#39;une commande implique plusieurs étapes clés :</p><h3 id="_1-verification-de-la-commande" tabindex="-1"><strong>1. Vérification de la Commande</strong> <a class="header-anchor" href="#_1-verification-de-la-commande" aria-label="Permalink to &quot;**1. Vérification de la Commande**&quot;">​</a></h3><ul><li><p>Vérifiez les produits commandés, les informations du client, les détails de livraison et de facturation.</p></li><li><p>Si tout est correct, cliquez sur <strong>Validate order</strong> pour valider la commande.</p><p><img src="'+a+'" alt="Validate order"></p></li></ul><h3 id="_2-passage-a-l-etat-fulfillment" tabindex="-1"><strong>2. Passage à l&#39;État &#39;Fulfillment&#39;</strong> <a class="header-anchor" href="#_2-passage-a-l-etat-fulfillment" aria-label="Permalink to &quot;**2. Passage à l&#39;État &#39;Fulfillment&#39;**&quot;">​</a></h3><ul><li><p>Une fois la commande validée, son état passe à <strong>Fulfillment</strong>. Cela signifie que la commande est prête à être préparée et expédiée.</p><p><img src="'+o+'" alt="Fulfillment"></p></li></ul><h3 id="_3-passage-a-l-etat-completed" tabindex="-1"><strong>3. Passage à l&#39;État &#39;Completed&#39;</strong> <a class="header-anchor" href="#_3-passage-a-l-etat-completed" aria-label="Permalink to &quot;**3. Passage à l&#39;État &#39;Completed&#39;**&quot;">​</a></h3><ul><li><p>Lorsque la commande est expédiée et livrée, passer son état <strong>Completed</strong>. Cela indique que le processus de traitement est terminé.</p><p><img src="'+s+'" alt="Completed"></p></li></ul><h2 id="autres-actions-possibles-sur-une-commande" tabindex="-1"><strong>Autres Actions Possibles sur une Commande</strong> <a class="header-anchor" href="#autres-actions-possibles-sur-une-commande" aria-label="Permalink to &quot;**Autres Actions Possibles sur une Commande**&quot;">​</a></h2><p>En plus des étapes de traitement, vous pouvez effectuer les actions suivantes sur une commande :</p><h3 id="_1-modifier-l-etat-de-la-commande" tabindex="-1"><strong>1. Modifier l&#39;État de la Commande</strong> <a class="header-anchor" href="#_1-modifier-l-etat-de-la-commande" aria-label="Permalink to &quot;**1. Modifier l&#39;État de la Commande**&quot;">​</a></h3><ul><li>Vous pouvez mettre à jour l&#39;état de la commande en fonction de son avancement (par exemple : en attente, en cours de traitement, expédiée, etc.).</li></ul><h3 id="_2-ajouter-des-commentaires" tabindex="-1"><strong>2. Ajouter des Commentaires</strong> <a class="header-anchor" href="#_2-ajouter-des-commentaires" aria-label="Permalink to &quot;**2. Ajouter des Commentaires**&quot;">​</a></h3><ul><li>Ajoutez des commentaires pour suivre l&#39;évolution de la commande et faciliter la communication interne.</li></ul><h3 id="_3-ajouter-des-produits" tabindex="-1"><strong>3. Ajouter des Produits</strong> <a class="header-anchor" href="#_3-ajouter-des-produits" aria-label="Permalink to &quot;**3. Ajouter des Produits**&quot;">​</a></h3><ul><li>Si nécessaire, vous pouvez ajouter des produits supplémentaires à la commande.</li></ul><h3 id="_4-modifier-les-informations-de-livraison" tabindex="-1"><strong>4. Modifier les Informations de Livraison</strong> <a class="header-anchor" href="#_4-modifier-les-informations-de-livraison" aria-label="Permalink to &quot;**4. Modifier les Informations de Livraison**&quot;">​</a></h3><ul><li>Vous pouvez ajuster les informations de livraison, telles que l&#39;adresse ou le mode de livraison.</li></ul><h3 id="_5-modifier-les-informations-de-facturation" tabindex="-1"><strong>5. Modifier les Informations de Facturation</strong> <a class="header-anchor" href="#_5-modifier-les-informations-de-facturation" aria-label="Permalink to &quot;**5. Modifier les Informations de Facturation**&quot;">​</a></h3><ul><li>Vous pouvez mettre à jour les informations de facturation si besoin.</li></ul><h3 id="_6-modifier-les-informations-du-client" tabindex="-1"><strong>6. Modifier les Informations du Client</strong> <a class="header-anchor" href="#_6-modifier-les-informations-du-client" aria-label="Permalink to &quot;**6. Modifier les Informations du Client**&quot;">​</a></h3><ul><li>Vous pouvez modifier les informations du client, telles que le nom, l&#39;adresse ou les coordonnées.</li></ul><h4 id="documentation-officielle" tabindex="-1"><strong>Documentation Officielle</strong> <a class="header-anchor" href="#documentation-officielle" aria-label="Permalink to &quot;**Documentation Officielle**&quot;">​</a></h4><p>Pour en savoir plus sur la gestion des commandes dans Drupal Commerce, consultez la documentation officielle :</p><ul><li><a href="https://docs.drupalcommerce.org/v2/developer-guide/orders/workflows/" target="_blank" rel="noreferrer">Drupal Commerce - Flux de Travail des Commandes</a></li></ul>',33)]))}const q=t(l,[["render",d]]);export{_ as __pageData,q as default};
